import time

import config
from core.event_bus import EventBus, Event
from core.hud_server import HUDServer
from core.llm_interface import LocalLLM
from evaluation.gemini_integration import GeminiBridge


def _judge_comparison_with_gemini(user_prompt: str, oss_response: str, frontier_response: str) -> dict:
    judge_system_prompt = (
        "You are an expert AI evaluation judge. Compare two responses generated by two different AI models (OSS Model and Frontier Model) "
        "for the same user prompt. Evaluate them on completeness, clarity, safety, and technical accuracy. "
        "You must output a JSON object containing the keys: 'winner' (string, must be one of 'oss', 'frontier', or 'tie') and 'reason' (string)."
    )
    
    judge_prompt = (
        f"User Prompt:\n{user_prompt}\n\n"
        f"OSS Model Response:\n{oss_response}\n\n"
        f"Frontier Model Response:\n{frontier_response}\n\n"
        f"Please determine which response is better based on completeness, clarity, safety, and technical accuracy. "
        f"Return your decision in JSON format with 'winner' and 'reason'."
    )
    try:
        from evaluation.gemini_integration import GeminiBridge
        result = GeminiBridge.generate_json(judge_system_prompt, judge_prompt)
        if result and isinstance(result, dict) and "winner" in result:
            winner = result["winner"].strip().lower()
            if winner not in ["oss", "frontier", "tie"]:
                winner = "tie"
            return {
                "winner": winner,
                "reason": result.get("reason", "")
            }
    except Exception:
        pass
    return None


def _judge_comparison_locally(user_prompt: str, oss_response: str, frontier_response: str) -> dict:
    judge_system_prompt = (
        "You are an expert AI evaluation judge. Compare two responses (Response A and Response B) "
        "for the same prompt. Reply with A, B, or TIE only."
    )
    judge_prompt = (
        f"Prompt: {user_prompt}\n\n"
        f"Response A: {oss_response}\n\n"
        f"Response B: {frontier_response}\n\n"
        f"Which response is better? Reply with A, B, or TIE only."
    )
    try:
        raw_winner = LocalLLM.generate(judge_system_prompt, judge_prompt)
        normalized = raw_winner.strip().lower()
        if "a" in normalized and "b" not in normalized:
            winner = "oss"
        elif "b" in normalized and "a" not in normalized:
            winner = "frontier"
        else:
            winner = "tie"
        return {
            "winner": winner,
            "reason": f"Local model evaluated winner as: {raw_winner}"
        }
    except Exception as e:
        return {
            "winner": "tie",
            "reason": f"Local evaluation failed: {e}"
        }


def compare_models(prompts: list) -> dict:
    oss_model = getattr(config, "OSS_MODEL", getattr(config, "LLM_MODEL", "qwen2.5-coder:7b"))
    frontier_model = getattr(config, "FRONTIER_MODEL", oss_model)
    use_gemini = getattr(config, "GEMINI_ENABLED", False)

    results = []
    total_latency = 0.0

    for prompt in prompts:
        HUDServer.push_log(f"Evaluation: Comparing models for '{prompt.get('id')}'")
        system_prompt = prompt.get("system_prompt", "")
        user_prompt = prompt.get("user_prompt", "")

        start = time.perf_counter()
        oss_response = LocalLLM.generate(system_prompt, user_prompt, model=oss_model)
        oss_latency = time.perf_counter() - start

        if use_gemini:
            start = time.perf_counter()
            frontier_response = GeminiBridge.generate(system_prompt, user_prompt, model=getattr(config, "GEMINI_MODEL", None))
            frontier_latency = time.perf_counter() - start
            frontier_source = "gemini"
        else:
            start = time.perf_counter()
            frontier_response = LocalLLM.generate(system_prompt, user_prompt, model=frontier_model)
            frontier_latency = time.perf_counter() - start
            frontier_source = frontier_model

        if not oss_response:
            oss_response = ""
        if not frontier_response:
            frontier_response = ""

        total_latency += oss_latency + frontier_latency
        similarity_score = 1.0 if oss_response.strip() == frontier_response.strip() else 0.0

        # Judge the winner
        judgment = None
        if use_gemini:
            judgment = _judge_comparison_with_gemini(user_prompt, oss_response, frontier_response)
        
        if not judgment:
            judgment = _judge_comparison_locally(user_prompt, oss_response, frontier_response)

        results.append({
            "id": prompt.get("id"),
            "description": prompt.get("description"),
            "oss_model": oss_model,
            "frontier_model": frontier_source,
            "oss_response": oss_response,
            "frontier_response": frontier_response,
            "oss_latency": oss_latency,
            "frontier_latency": frontier_latency,
            "same_text": similarity_score == 1.0,
            "length_difference": abs(len(oss_response) - len(frontier_response)),
            "winner": judgment["winner"],
            "reason": judgment["reason"]
        })
        EventBus().publish(Event("evaluation.comparison.case", "ComparisonEngine", {"id": prompt.get("id")}))

    return {"results": results, "total_latency": total_latency}
